document.addEventListener("DOMContentLoaded",()=>{if(!(window.location.pathname==="/"||window.location.pathname==="/index"))return;const n=document.querySelector("#about-switch input"),e=document.querySelectorAll(".about-content");if(!n||e.length<2)return;const[t,o]=e,s=()=>{n.checked?(t.classList.add("display-none"),o.classList.remove("display-none")):(t.classList.remove("display-none"),o.classList.add("display-none"))};n.addEventListener("change",s),s()});
